@page "/courses"
@inject ICatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" class="row g-3 mb-4" enhance>
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or instructor..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject ICatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses" class="btn btn-secondary">Back to Courses</a>
}
else
{
    <PageTitle>@course.CourseCode - @course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <span class="badge bg-secondary fs-6">@course.CourseCode</span>
    <span class="badge bg-info fs-6">@course.Credits Credits</span>
    <span class="badge bg-success fs-6">@course.DepartmentName</span>

    <section class="mt-4">
        <h2>Description</h2>
        <p>@course.Description</p>
    </section>

    <section class="mt-4">
        <h2>Schedule</h2>
        <p><strong>@course.Schedule</strong></p>
    </section>

    <section class="mt-4">
        <h2>Instructor</h2>
        <h5>@course.InstructorName</h5>
        <p>@course.InstructorBio</p>
    </section>

    <div class="mt-4">
        <a href="enroll?courseId=@course.Id" class="btn btn-primary">Request Enrollment</a>
        <a href="courses" class="btn btn-outline-secondary ms-2">Back to Courses</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

@page "/enroll"
@inject ICatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will receive a confirmation via your university email.</p>
        <a href="courses" class="btn btn-outline-success mt-2">Browse More Courses</a>
    </div>
}
else
{
    <form method="post" class="col-md-8" @formname="enrollment">
        <AntiforgeryToken />

        @if (validationErrors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in validationErrors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name</label>
            <input type="text" id="fullName" name="Model.FullName" value="@Model.FullName" class="form-control" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control"
                   placeholder="e.g. STU12345" />
            <div class="form-text">6-10 uppercase alphanumeric characters.</div>
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select">
                <option value="0">-- Select a course --</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode - @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private string selectedCourseTitle = string.Empty;
    private List<string> validationErrors = new();

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (!HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET"))
            return;

        validationErrors.Clear();

        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, results, true))
        {
            validationErrors.AddRange(results.Select(r => r.ErrorMessage ?? "Invalid input."));
            return;
        }

        if (Catalog.SubmitEnrollment(Model))
        {
            selectedCourseTitle = Catalog.GetCourse(Model.CourseId)?.Title ?? "Unknown";
            submitted = true;
        }
        else
        {
            validationErrors.Add("The selected course could not be found.");
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContextAccessor { get; set; }
}

