<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will receive a confirmation via your university email.</p>
        <a href="courses" class="btn btn-outline-success mt-2">Browse More Courses</a>
    </div>
}
else
{
    <form method="post" class="col-md-8" @formname="enrollment">
        <AntiforgeryToken />

        @if (validationErrors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in validationErrors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name</label>
            <input type="text" id="fullName" name="Model.FullName" value="@Model.FullName" class="form-control" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control"
                   placeholder="e.g. STU12345" />
            <div class="form-text">6-10 uppercase alphanumeric characters.</div>
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select">
                <option value="0">-- Select a course --</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode - @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private string selectedCourseTitle = string.Empty;
    private List<string> validationErrors = new();

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }

        var httpContext = HttpContextAccessor.HttpContext;
        if (httpContext is null || !HttpMethods.IsPost(httpContext.Request.Method))
            return;

        validationErrors.Clear();

        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, results, true))
        {
            validationErrors.AddRange(results.Select(r => r.ErrorMessage ?? "Invalid input."));
            return;
        }

        if (Catalog.SubmitEnrollment(Model))
        {
            selectedCourseTitle = Catalog.GetCourse(Model.CourseId)?.Title ?? "Unknown";
            submitted = true;
        }
        else
        {
            validationErrors.Add("The selected course could not be found.");
        }
    }
}

